# Pulumi ComponentResource: Service + Bucket + DB + IAM

Here's a complete implementation with stack config support for dev/prod.

## `appStack.ts` — The ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppStackArgs {
    /** Environment name, e.g. "dev" or "prod" */
    environment: string;
    /** RDS instance class, e.g. db.t3.micro / db.t3.medium */
    dbInstanceClass: string;
    /** Multi-AZ for RDS (prod) */
    dbMultiAz: boolean;
    /** KMS-encrypt RDS storage (prod) */
    dbEncrypted: boolean;
    /** Backup retention in days (>= 7 required) */
    dbBackupRetentionDays: number;
    /** DB master username */
    dbUsername: pulumi.Input<string>;
    /** DB master password — pass a ConfigSecret so it stays encrypted */
    dbPassword: pulumi.Input<string>;
    /** OIDC provider ARN for IRSA trust (least-privilege service role) */
    oidcProviderArn: pulumi.Input<string>;
    /** OIDC provider URL (host part), used in trust condition */
    oidcProviderUrl: pulumi.Input<string>;
    /** K8s service account subject, e.g. system:serviceaccount:app:web */
    serviceAccountSubject: string;
    /** VPC subnet ids for the DB subnet group */
    dbSubnetIds: pulumi.Input<string>[];
    /** Optional replication region for the bucket (prod) */
    bucketReplicaRegion?: string;
    tags?: { [k: string]: string };
}

export class AppStack extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;
    public readonly serviceRoleArn: pulumi.Output<string>;

    constructor(
        name: string,
        args: AppStackArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("app:index:AppStack", name, {}, opts);
        const parent = { parent: this };
        const isProd = args.environment === "prod";
        const tags = { Environment: args.environment, ManagedBy: "pulumi", ...args.tags };

        // ------------------------------------------------------------------
        // 1. S3 bucket: versioning + encryption + block public access
        // ------------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags,
        }, parent);

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, parent);

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: { sseAlgorithm: "AES256" },
            }],
        }, parent);

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, parent);

        // Prod: cross-region replication to us-west-2
        if (isProd && args.bucketReplicaRegion) {
            const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
                region: args.bucketReplicaRegion as aws.Region,
            }, parent);

            const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
                tags,
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replicaBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replicaProvider });

            const replRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
                tags,
            }, parent);

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replRole.id,
                policy: pulumi.all([bucket.arn, replicaBucket.arn]).apply(
                    ([src, dst]) => JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Effect: "Allow",
                                Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                                Resource: [src],
                            },
                            {
                                Effect: "Allow",
                                Action: [
                                    "s3:GetObjectVersionForReplication",
                                    "s3:GetObjectVersionAcl",
                                    "s3:GetObjectVersionTagging",
                                ],
                                Resource: [`${src}/*`],
                            },
                            {
                                Effect: "Allow",
                                Action: [
                                    "s3:ReplicateObject",
                                    "s3:ReplicateDelete",
                                    "s3:ReplicateTags",
                                ],
                                Resource: [`${dst}/*`],
                            },
                        ],
                    }),
                ),
            }, parent);

            new aws.s3.BucketReplicationConfig(`${name}-assets-replication`, {
                role: replRole.arn,
                bucket: bucket.id,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    filter: {},
                    deleteMarkerReplication: { status: "Enabled" },
                    destination: {
                        bucket: replicaBucket.arn,
                        storageClass: "STANDARD",
                    },
                }],
            }, parent);
        }

        // ------------------------------------------------------------------
        // 2. RDS PostgreSQL: deletion protection, backups >= 7d, private
        // ------------------------------------------------------------------
        const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.dbSubnetIds,
            tags,
        }, parent);

        const db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: 20,
            dbName: "appdb",
            username: args.dbUsername,
            password: args.dbPassword,
            dbSubnetGroupName: subnetGroup.name,
            multiAz: args.dbMultiAz,
            storageEncrypted: args.dbEncrypted,
            deletionProtection: true,               // AC #2
            backupRetentionPeriod: args.dbBackupRetentionDays, // >= 7
            publiclyAccessible: false,              // AC #2
            skipFinalSnapshot: !isProd,
            finalSnapshotIdentifier: isProd ? `${name}-db-final` : undefined,
            applyImmediately: !isProd,
            tags,
        }, parent);

        // ------------------------------------------------------------------
        // 3. IAM role for service account (IRSA / OIDC trust)
        // ------------------------------------------------------------------
        const serviceRole = new aws.iam.Role(`${name}-svc-role`, {
            assumeRolePolicy: pulumi
                .all([args.oidcProviderArn, args.oidcProviderUrl])
                .apply(([arn, url]) => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: arn },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${url}:sub`]: args.serviceAccountSubject,
                                [`${url}:aud`]: "sts.amazonaws.com",
                            },
                        },
                    }],
                })),
            tags,
        }, parent);

        // Least-privilege: scoped to this bucket only, no wildcard actions
        new aws.iam.RolePolicy(`${name}-svc-policy`, {
            role: serviceRole.id,
            policy: bucket.arn.apply((bArn) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "BucketList",
                        Effect: "Allow",
                        Action: ["s3:ListBucket"],
                        Resource: [bArn],
                    },
                    {
                        Sid: "ObjectRW",
                        Effect: "Allow",
                        Action: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                        Resource: [`${bArn}/*`],
                    },
                ],
            })),
        }, parent);

        // ------------------------------------------------------------------
        // Outputs
        // ------------------------------------------------------------------
        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.endpoint;
        this.dbConnectionString = pulumi
            .all([args.dbUsername, args.dbPassword, db.endpoint, db.dbName])
            .apply(([u, p, e, n]) => `postgresql://${u}:${p}@${e}/${n}`);
        this.serviceRoleArn = serviceRole.arn;

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            dbEndpoint: this.dbEndpoint,
            serviceRoleArn: this.serviceRoleArn,
        });
    }
}
```

## `index.ts` — Wiring config to the component

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppStack } from "./appStack";

const config = new pulumi.Config();
const env = pulumi.getStack(); // "dev" or "prod"

const app = new AppStack("web", {
    environment: env,
    dbInstanceClass: config.require("dbInstanceClass"),
    dbMultiAz: config.requireBoolean("dbMultiAz"),
    dbEncrypted: config.requireBoolean("dbEncrypted"),
    dbBackupRetentionDays: config.requireNumber("dbBackupRetentionDays"),
    dbUsername: config.require("dbUsername"),
    dbPassword: config.requireSecret("dbPassword"), // ConfigSecret, encrypted at rest
    oidcProviderArn: config.require("oidcProviderArn"),
    oidcProviderUrl: config.require("oidcProviderUrl"),
    serviceAccountSubject: config.require("serviceAccountSubject"),
    dbSubnetIds: config.requireObject<string[]>("dbSubnetIds"),
    bucketReplicaRegion: config.get("bucketReplicaRegion"),
});

export const bucketName = app.bucketName;
export const dbEndpoint = app.dbEndpoint;
export const serviceRoleArn = app.serviceRoleArn;
// Marked secret automatically since it derives from a secret input
export const dbConnectionString = app.dbConnectionString;
```

## Stack configs (environment isolation)

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  project:dbInstanceClass: db.t3.micro
  project:dbMultiAz: "false"
  project:dbEncrypted: "false"
  project:dbBackupRetentionDays: "7"
  project:dbUsername: appadmin
  project:serviceAccountSubject: "system:serviceaccount:app:web"
  project:oidcProviderArn: "arn:aws:iam::111111111111:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVXXXX"
  project:oidcProviderUrl: "oidc.eks.us-east-1.amazonaws.com/id/DEVXXXX"
  project:dbSubnetIds:
    - subnet-aaa
    - subnet-bbb
```

Set the secret (never in plaintext Git):

```bash
pulumi config set --secret --stack dev project:dbPassword 'S0meDevPass!'
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  project:dbInstanceClass: db.t3.medium
  project:dbMultiAz: "true"
  project:dbEncrypted: "true"
  project:dbBackupRetentionDays: "14"
  project:dbUsername: appadmin
  project:bucketReplicaRegion: us-west-2
  project:serviceAccountSubject: "system:serviceaccount:app:web"
  project:oidcProviderArn: "arn:aws:iam::222222222222:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/PRODXXXX"
  project:oidcProviderUrl: "oidc.eks.us-east-1.amazonaws.com/id/PRODXXXX"
  project:dbSubnetIds:
    - subnet-ccc
    - subnet-ddd
```

```bash
pulumi config set --secret --stack prod project:dbPassword 'StrongProdPass!'
```

## How this maps to the acceptance criteria

| Criteria | Implementation |
|---|---|
| **Bucket** versioning + encryption + no public | `BucketVersioningV2` Enabled, `AES256` SSE, `BucketPublicAccessBlock` all-true |
| **RDS** deletion protection, backups ≥7d, private | `deletionProtection: true`, `backupRetentionPeriod` from config (7/14), `publiclyAccessible: false` |
| **Secret** never plaintext | `config.requireSecret` (ConfigSecret) — encrypted in `Pulumi.<env>.yaml` and in state |
| **IAM** least privilege, no wildcards | Scoped `s3:Get/Put/Delete` on this bucket ARN only; OIDC trust condition |
| **Environment isolation** | Separate stacks (`dev`/`prod`) → separate state; different accounts/OIDC |
| **Prod cross-region replication** | `BucketReplicationConfig` to `us-west-2` only when `isProd` |

```bash
pulumi stack init dev  && pulumi up --stack dev
pulumi stack init prod && pulumi up --stack prod
```

Deploying `prod` never touches `dev` state — each stack is an independent state file.

